import Configuration
import Crypto
import Foundation
import _NIOFileSystem

/// Protocol 1.17, Dify's local UploadFile backend. A key is generated by the server, never a client path.
struct FileStorageConfig: Sendable {
    var directory: String
    var signingKey: String
    var externalURL: String
    var internalURL: String
    var accessSeconds: Int
    var fileMiB: Int
    var imageMiB: Int
    var audioMiB: Int
    var videoMiB: Int
    var blockedExtensions: Set<String>

    init(reader: ConfigReader) {
        directory = reader.string(forKey: "collab.files.directory", default: "./storage/uploads")
        signingKey = reader.string(forKey: "collab.files.signingKey", isSecret: true, default: "")
        externalURL = reader.string(forKey: "collab.files.url", default: "").trimmingCharacters(in: .whitespaces)
        internalURL = reader.string(forKey: "collab.files.internalUrl", default: "").trimmingCharacters(in: .whitespaces)
        accessSeconds = max(1, reader.int(forKey: "collab.files.accessSeconds", default: 300))
        fileMiB = min(1024, max(0, reader.int(forKey: "collab.files.fileMib", default: 15)))
        imageMiB = min(1024, max(0, reader.int(forKey: "collab.files.imageMib", default: 10)))
        audioMiB = min(1024, max(0, reader.int(forKey: "collab.files.audioMib", default: 50)))
        videoMiB = min(1024, max(0, reader.int(forKey: "collab.files.videoMib", default: 100)))
        blockedExtensions = Set(reader.string(forKey: "collab.files.blockedExtensions", default: "")
            .split(separator: ",").map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased().trimmingCharacters(in: CharacterSet(charactersIn: ".")) })
    }

    /// No default secret and no host inferred from an untrusted request.
    var isConfigured: Bool {
        signingKey.utf8.count >= 32 && Self.validOrigin(externalURL) &&
            (internalURL.isEmpty || Self.validOrigin(internalURL)) && !directory.isEmpty
    }

    static func validOrigin(_ raw: String) -> Bool {
        guard let u = URLComponents(string: raw), ["http", "https"].contains(u.scheme?.lowercased() ?? ""),
              u.host?.isEmpty == false, u.user == nil, u.password == nil, u.query == nil, u.fragment == nil else { return false }
        return true
    }

    static let images: Set<String> = ["jpg", "jpeg", "png", "webp", "gif", "bmp", "heic", "heif"]
    static let audio: Set<String> = ["mp3", "mpga", "m4a", "wav", "webm", "amr", "flac", "ogg", "aac"]
    static let video: Set<String> = ["mp4", "mov", "mpeg", "mpg", "webm", "mkv", "avi"]
    static let text: Set<String> = ["txt", "md", "markdown", "json", "csv", "html", "htm"]

    func limit(for ext: String) -> Int {
        let mib = Self.images.contains(ext) ? imageMiB : Self.video.contains(ext) ? videoMiB : Self.audio.contains(ext) ? audioMiB : fileMiB
        return min(mib, 1024) * 1024 * 1024
    }

    var maximumBody: Int { min(max(fileMiB, imageMiB, audioMiB, videoMiB), 1024) * 1024 * 1024 + 64 * 1024 }
}

/// Dify 1.17.1 core/app/workflow/file_runtime.py. Secrets never form part of URLs or error descriptions.
struct FileSigner: Sendable {
    private let key: SymmetricKey
    let lifetime: Int
    let baseURL: String

    init?(config: FileStorageConfig, internalAudience: Bool = false) {
        guard config.isConfigured else { return nil }
        key = SymmetricKey(data: Data(config.signingKey.utf8))
        lifetime = config.accessSeconds
        baseURL = (internalAudience && !config.internalURL.isEmpty ? config.internalURL : config.externalURL)
            .trimmingCharacters(in: CharacterSet(charactersIn: "/"))
    }

    func sign(id: String, kind: String = "file", timestamp: String, nonce: String) -> String {
        let bytes = Data("\(kind)-preview|\(id)|\(timestamp)|\(nonce)".utf8)
        return Data(HMAC<SHA256>.authenticationCode(for: bytes, using: key)).base64EncodedString()
            .replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_")
    }

    func verify(id: String, kind: String, timestamp: String, nonce: String, signature: String, now: Date = Date()) -> Bool {
        guard ["file", "image"].contains(kind), UUID(uuidString: id) != nil,
              let seconds = Int64(timestamp), timestamp == String(seconds), nonce.utf8.count == 32,
              nonce.utf8.allSatisfy({ (48...57).contains($0) || (97...102).contains($0) }),
              signature.utf8.count <= 128,
              let mac = Data(base64Encoded: signature.replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")) else { return false }
        // Dify's public contract is the age check; the signer only ever issues current timestamps.
        let age = now.timeIntervalSince1970.rounded(.down) - Double(seconds)
        guard age <= Double(lifetime) else { return false }
        return HMAC<SHA256>.isValidAuthenticationCode(mac,
            authenticating: Data("\(kind)-preview|\(id)|\(timestamp)|\(nonce)".utf8), using: key)
    }

    func url(id: String, kind: String = "file", attachment: Bool = false, now: Date = Date(), nonce suppliedNonce: String? = nil) -> String {
        let timestamp = String(Int64(now.timeIntervalSince1970.rounded(.down)))
        let nonce = suppliedNonce ?? (0..<16).map { _ in String(format: "%02x", UInt8.random(in: 0...255)) }.joined()
        let signature = sign(id: id, kind: kind, timestamp: timestamp, nonce: nonce)
        let safe = CharacterSet(charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_")
        let encoded = signature.addingPercentEncoding(withAllowedCharacters: safe)!
        return "\(baseURL)/files/\(id)/\(kind)-preview?timestamp=\(timestamp)&nonce=\(nonce)&sign=\(encoded)" +
            (attachment ? "&as_attachment=true" : "")
    }
}

enum BlobStoreError: Error { case invalidKey, invalidRoot, missing }

struct BlobInfo: Sendable { var size: Int64 }

/// Awaiting consume gives the HTTP writer backpressure; no unbounded stream buffers or whole-file reads.
protocol BlobStore: Sendable {
    func putAtomic(key: String, bytes: Data) async throws
    nonisolated(nonsending) func readStream(key: String, range: Range<Int64>, consume: (Data) async throws -> Void) async throws
    func info(key: String) async throws -> BlobInfo?
    func delete(key: String) async throws
}

struct LocalBlobStore: BlobStore {
    let root: String
    private let fs = FileSystem.shared

    init(directory: String) throws {
        let path = URL(fileURLWithPath: directory, isDirectory: true).standardizedFileURL.path
        guard !directory.isEmpty, path != "/" else { throw BlobStoreError.invalidRoot }
        root = path
    }

    /// Exactly two UUID components; filenames, extensions and references are metadata, never paths.
    private func path(_ key: String) throws -> FilePath {
        let parts = key.split(separator: "/", omittingEmptySubsequences: false)
        guard parts.count == 2, parts.allSatisfy({ UUID(uuidString: String($0)) != nil && !$0.contains("..") }) else { throw BlobStoreError.invalidKey }
        return FilePath("\(root)/\(key)")
    }

    func putAtomic(key: String, bytes: Data) async throws {
        let final = try path(key)
        let parent = "\(root)/\(key.split(separator: "/")[0])"
        try await fs.createDirectory(at: FilePath(parent), withIntermediateDirectories: true, permissions: .ownerReadWriteExecute)
        let temporary = FilePath("\(parent)/.pending-\(key.split(separator: "/")[1])")
        do {
            var options = OpenOptions.Write.newFile(replaceExisting: false, permissions: .ownerReadWrite)
            options.followSymbolicLinks = false
            try await bytes.write(toFileAt: temporary, options: options)
            try await fs.moveItem(at: temporary, to: final)
        } catch {
            _ = try? await fs.removeItem(at: temporary)
            throw error
        }
    }

    nonisolated(nonsending) func readStream(key: String, range: Range<Int64>, consume: (Data) async throws -> Void) async throws {
        let location = try path(key)
        // Match Vapor FileIO: the writer stays on its caller executor, and close survives cancellation.
        let handle = try await fs.openFile(forReadingAt: location, options: .init(followSymbolicLinks: false))
        defer { await Task { try? await handle.close() }.value }
        for try await chunk in handle.readChunks(in: range, chunkLength: .bytes(128 * 1024)) {
            try await consume(Data(chunk.readableBytesView))
        }
    }

    func info(key: String) async throws -> BlobInfo? {
        guard let info = try await fs.info(forFileAt: path(key)), info.type == .regular else { return nil }
        return BlobInfo(size: Int64(info.size))
    }

    func delete(key: String) async throws {
        let location = try path(key)
        _ = try await fs.removeItem(at: location)
        let parts = key.split(separator: "/")
        _ = try await fs.removeItem(at: FilePath("\(root)/\(parts[0])/.pending-\(parts[1])"))
    }
}
